'use strict';
const sbConfig=window.OCCCI_SUPABASE_CONFIG;
const sbAccount={session:null,profile:null,mode:'login'};
const sbSessionKey='occci.supabase.session.v1';
function sbStore(session){sbAccount.session=session;try{if(session)localStorage.setItem(sbSessionKey,JSON.stringify(session));else localStorage.removeItem(sbSessionKey);}catch{}}
async function sbRequest(path,{method='GET',body,authenticated=false}={}){
 const headers={apikey:sbConfig.publishableKey,'Content-Type':'application/json'};
 if(authenticated){await sbEnsureSession();headers.Authorization='Bearer '+sbAccount.session.access_token;}
 const response=await fetch(sbConfig.url+path,{method,headers,body:body?JSON.stringify(body):undefined,cache:'no-store'});
 let data;try{data=await response.json();}catch{data=null;}
 if(!response.ok){const code=data?.code||data?.error_code;const missing=code==='PGRST205'||code==='42P01';throw new Error(missing?'Member database setup is pending. Ask the administrator to run the Supabase setup SQL.':data?.msg||data?.message||data?.error_description||data?.error||'Unable to connect. Please try again.');}
 return data;
}
async function sbEnsureSession(){
 if(!sbAccount.session)throw new Error('Please sign in.');
 if(sbAccount.session.expires_at<Date.now()/1000+60){try{const data=await sbRequest('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:sbAccount.session.refresh_token}});sbStore({...data,expires_at:Date.now()/1000+data.expires_in});}catch(error){sbStore(null);sbAccount.profile=null;throw error;}}
}
function sbMessage(message){const node=document.getElementById('sbMessage');if(node)node.textContent=message;}
function sbAccountView(){
 if(sbAccount.session){const p=sbAccount.profile;return `<p class="smalltext">Signed in: ${e(sbAccount.session.user?.email||'Member')}</p>${p?`<div class="info-strip">${icon('shield')}<span>${e(p.membership_status)} membership · ${e(branchName(p.branch_id))} branch</span></div><form onsubmit="event.preventDefault();sbSaveProfile(this)"><div class="form-grid spacer"><label class="full">Full name<input name="name" value="${e(p.full_name)}" maxlength="100" required></label><label class="full">Temporary avatar<select name="avatar">${defaultAvatars.map(([id,label])=>`<option value="${id}" ${p.avatar===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="dialog-actions"><button type="submit" class="primary">Save member profile</button></div></form>`:'<p>Your member profile has not loaded yet.</p>'}<p class="smalltext">This account is stored in Supabase. The dashboard’s sample balances and admin demo remain illustrative.</p><div class="dialog-actions">${button('Reload profile','sbLoadProfile()','outline')}${button('Sign out','sbSignOut()','secondary')}</div><p id="sbMessage" role="status" aria-live="polite"></p>`;}
 return `<div class="tabs">${button('Sign in',"sbAccount.mode='login';openSupabaseAccount()",sbAccount.mode==='login'?'active':'')}${button('Register',"sbAccount.mode='register';openSupabaseAccount()",sbAccount.mode==='register'?'active':'')}</div><form onsubmit="event.preventDefault();sbSubmitAuth(this)"><div class="form-grid">${sbAccount.mode==='register'?`<label class="full">Full name<input name="name" autocomplete="name" maxlength="100" required></label><label class="full">Home branch<select name="branch">${branchOptions('BR-01')}</select></label><label class="full">Temporary avatar<select name="avatar">${defaultAvatars.map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select><span class="hint">You can register without uploading a photo.</span></label>`:''}<label class="full">Email<input type="email" name="email" autocomplete="email" required></label><label class="full">Password<input type="password" name="password" minlength="8" autocomplete="${sbAccount.mode==='register'?'new-password':'current-password'}" required></label></div><p class="smalltext">${sbAccount.mode==='register'?'Confirm your email to sign in. Online registration does not approve cooperative membership.':'Sign in to your Supabase member account.'}</p><div class="dialog-actions"><button type="submit" class="primary">${sbAccount.mode==='register'?'Create account':'Sign in'}</button></div><p id="sbMessage" role="status" aria-live="polite"></p></form>`;
}
function openSupabaseAccount(){openModal('Member account',sbAccountView());}
async function sbSubmitAuth(form){const submit=form.querySelector('[type=submit]');submit.disabled=true;sbMessage('Connecting…');const f=new FormData(form);try{
 if(sbAccount.mode==='register'){const result=await sbRequest('/auth/v1/signup',{method:'POST',body:{email:f.get('email'),password:f.get('password'),data:{full_name:f.get('name'),branch_id:f.get('branch'),avatar:f.get('avatar')}}});if(result.access_token){sbStore({...result,expires_at:Date.now()/1000+result.expires_in});await sbLoadProfile();}else{form.reset();sbMessage('Check your email for confirmation. Then return here to sign in.');}}
 else{const result=await sbRequest('/auth/v1/token?grant_type=password',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});sbStore({...result,expires_at:Date.now()/1000+result.expires_in});await sbLoadProfile();}
 }catch(error){sbMessage(error.message);}finally{submit.disabled=false;}}
async function sbLoadProfile(){try{await sbEnsureSession();const user=await sbRequest('/auth/v1/user',{authenticated:true});sbAccount.session.user=user;const profiles=await sbRequest('/rest/v1/occci_profiles?id=eq.'+encodeURIComponent(user.id)+'&select=id,full_name,branch_id,avatar,membership_status',{authenticated:true});sbAccount.profile=profiles?.[0]||null;openSupabaseAccount();if(!sbAccount.profile)sbMessage('No profile found. Ask the administrator to complete database setup.');}catch(error){if(!sbAccount.session)openSupabaseAccount();sbMessage(error.message);}}
async function sbSaveProfile(form){const submit=form.querySelector('[type=submit]');submit.disabled=true;const f=new FormData(form);try{await sbRequest('/rest/v1/occci_profiles?id=eq.'+encodeURIComponent(sbAccount.profile.id),{method:'PATCH',authenticated:true,body:{full_name:f.get('name'),avatar:f.get('avatar')}});await sbLoadProfile();sbMessage('Your profile has been saved.');}catch(error){sbMessage(error.message);}finally{submit.disabled=false;}}
async function sbSignOut(){try{await sbRequest('/auth/v1/logout',{method:'POST',authenticated:true});}catch{}sbStore(null);sbAccount.profile=null;openSupabaseAccount();}
try{const raw=JSON.parse(localStorage.getItem(sbSessionKey)||'null');if(raw?.access_token&&raw?.refresh_token)sbAccount.session=raw;}catch{}
